-- 2026-11-12 A2-2.1.2 第 2 条“数据库管理系统（DBMS）”：标题后内容逐句/逐条另起一行，颜色按图例
begin;
create temp table _kba212(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kba212 values (67, $kba212$[{"t":"list","id":"a2-2-1-2-b1","imp":"core","items":["1、==计算机系统==由==硬件系统==和==软件系统==两部分构成。","（1）==硬件系统:运算器、控制器、存储器、输入设备、输出设备==等五大部件","（2）==软件系统：系统软件和应用软件==。","==①、系统软件：操作系统、数据库管理系统、程序设计语言处理系统等==","==②、应用软件：文字处理软件、通信软件、图像处理软件等2 软件：==","==（1）软件=程序+数据+相关文档。==","==（2）程序就是要计算机做什么或完成什么功能的一组指令（语句），这些指令能够被计算机理解并执行的命令。==","==（3）数据：就是计算机执行程序过程中的输入数据和输出数据。==","==（4）相关文档就是程序开发、维护和操作有关的资料，不可缺少。==","^^（5）程序的特性：^^","^^①、不可见性∶是无形的，不能被人们直接观察、欣赏和评价。^^","^^②、适用性∶可以适应一类应用问题的需要。^^","^^③、依附性∶依附于特定的硬件、网络和其他软件。^^","^^④、复杂性∶规模越来越大，人力和物力消耗越来越高。^^","^^⑤、无磨损性∶功能和性能一般不会发生变化。^^","^^⑥、易复制性∶可以非常容易且无失真地进行复制。^^","^^⑦、不断演化∶有生命周期。^^","^^⑧、有限责任∶具有有限保证。^^","^^⑨、脆弱性∶容易遭受黑客、病毒、信息盗用等损害。^^","（6）程序与数据的关系：","①、程序所处理的对象和处理后得到的结果统称为数据（分别称为输入数据和输出数据）","②、程序需要有合理输入数据，才会产生有意义的输出数据","③、给同一个程序输入不同的数据，可以得到不同的输出数据","④、给不同的程序输入相同的数据，可以得到不同的输出数据","（7）软件的特点","①、软件是一种==逻辑==实体，具有抽象性；","②、软件的生产与硬件不同，它没有明显的制作过程；","③、软件在运行、使用期间不存在磨损、老化问题；","④、软件的开发、运行对计算机系统具有依赖性，受计算机系统的限制，这导致了软件移植的问题；","⑤、==软件复杂性高（固有有）==，成本昂贵；","⑥、软件开发涉及诸多的社会因素。","3 软件分类：","（1）按软件用途和功能作用分：","==①、应用软件：专门用于帮助最终用户解决各种具体应用问题的软件。==","可以分为==定制应用软件==和==通用应用软件==。"],"title":"","ordered":false},{"t":"table","id":"a2-2-1-2-b2","imp":"core","rows":[["==文字处理类==","==记事本Notepad（纯文本）、写字板Wordpad、微软Word、金山WPS 文字、 永中Office、Acrobat Reader 等=="],["==文字输入类==","==智能ABC、微软拼音、搜狗拼音、极品五笔、拼音加加、谷歌拼音=="],["==电子表格类==","==微软Excel、WPS 表格（金山公司，国产）等。=="],["==演示类 幻灯片==","==微软PowerPoint、 WPS 演示（金山公司，国产）等=="],["网页制作类","FrontPage、Dreamweaver、Web Page Maker、ASP Maker"],["网页浏览类","微软IE、傲游Maxthon、腾讯TT、Mozilla Firefox"],["搜索引擎类","Baidu、Google、北大天网、搜狐Sogou、新浪爱问、网易有道、雅虎易搜"],["杀毒软件类","瑞星、诺顿、卡巴斯基、金山毒霸、江民KV、趋势科技"],["软件防火墙类","瑞星个人防火墙、江民防火墙、360 防火墙、天网防火墙、风云防火墙"],["==图像处理类==","==Paint、Photo Editor、PhotoImpact、ACDSee32、Adobe Photoshop=="],["==矢量绘图软件==","==Corel Draw、Illustrator、Freehand、Microsoft Visio、Adobe Flash、3D Max=="],["==数字视频编辑软件==","==Adobe Premiere、Windows Movie Maker、Video Edit Magic、PowerDirector=="],["==数字声音编辑软件==","==CoolEdit、GoldWave、Adobe Audition、Nero wave Editor=="],["==媒体播放软件==","==暴风影音、Windows Media Player、RealPlayer、QuickTime、千千静听、 Winamp=="],["==网络聊天类==","==腾讯QQ、微软MSN、网易POPO、新浪UC、移动飞信、阿里旺旺=="],["解/压缩类","WinRAR、WinZip、7-Zip、ChinaZip、Zipghost"],["下载工具类","迅雷Thunder、网际快车FlashGet、比特彗星BitComet、电驴emule、腾讯旋风"],["邮件收发类","Outlook Express、Foxmail、DreamMail、Koomail、U-Mail"],["网络电视类","PPlive、PPStream、QQLive、UUsee、TVKoo、CCTV Box、迅雷看看"],["FTP 工具类","Serv-U FTP、CuteFTP、TurboFTP、ChinaFTP、LeapFTP"]],"title":"","headers":["通用软件类型","软件举例"]},{"t":"list","id":"a2-2-1-2-b3","imp":"core","items":["②、==系统软件：系统软件是给用户使用计算机提供方便、为应用软件的运行和开发提供服务与支持、使计算机安全可靠高效地运行的必不可少的软件=="],"title":"","ordered":false},{"t":"table","id":"a2-2-1-2-b4","imp":"core","rows":[["==操作系统（OS）==","==Windows、Unix、Linux、安卓、HarmonyOS（鸿蒙OS）等=="],["==基本输入/输出系统==","==BIOS=="],["==程序开发工具与环境==","==编译器、解释器、汇编程序（汇编器）、开发工具与平台=="],["==数据库管理系统(DBMS)==","==MySQL 、Oracle 、Access 、DB2 、SQL Server 、Sybase 、VFP 、 PostgreSQL、NoSQL（大数据中常用：BigTable、Redis、MongoDB、 Neo4J、Hazelcast）=="],["==实用程序==","==磁盘清理程序、备份程序、杀毒软件、防火墙等=="]],"title":"","headers":["==软件类型==","==软件举例=="]},{"t":"list","id":"a2-2-1-2-b5","imp":"core","items":["（2）==按知识产权分：==","==①、商品软件：得先购买后使用，受到版权和许可证保护。==","==例如：Windows 操作系统等==","==②、==@@共享软件（试用软件）：具有版权，可免费试用一段时间，允许拷贝和散发（但不可修改），试用期满后需交费才能继续使用@@==例如：微软Visio 等==","==③、==@@自由软件（开源软件）：用户可共享，并允许随意拷贝、修改其源代码，允许销售和自由传播。@@","==例如：Linux(CentOS)、Linux(Ubuntu)等==","==④、免费软件：无需付费即可获得的软件。例如 PDF 阅读器、Flash 播放器、QQ、微信等自由软件很多是免费软件；免费软件不全是自由软件==4 ==软件版本==","==（1）==@@版权授予软件作者(版权所有者)享有下列权利：拷贝、发布、修改、署名、出售、等@@","==（2）软件许可证也称为“许可证协议”，它规定了计算机软件使用方式的法律合同，软件使用有哪些额外的限制，有哪些额外的权利等==","==（3）许可证的类型：单用户许可证、多用户许可证、并发用户许可证、定点许可证等。==","==（4）==@@用户购买了一个软件后，仅仅得到了该软件的使用权，并没有它的版权。@@","==（5）通过购买多用户许可证，允许将一个软件安装在若干台计算机上使用，或者允许所安装的一份软件同时被若干用户使用。==","2、==数据库管理系统（DBMS）==","了解了数据和数据库的概念，下一个问题就是如何科学地组织和存储数据、如何高效地获取和维护数据，完成这个任务的是一个==系统软件==——数据库管理系统。","==数据库管理系统是位于用户与操作系统之间的一层数据管理软件。==","数据库管理系统和操作系统一样是计算机的基础软件，也是一个大型复杂的软件系统。","^^它的主要功能包括：^^","（1）==数据定义功能==","（2）^^数据组织、存储和管理^^","（3）^^数据操纵功能^^","（4）^^数据库的事务管理和运行管理^^","（5）数据库的建立和维护功能等。","3、==按软件权益分类==：^^按软件权益分^^：软件分为商品软件（受所有法律保护）、共享软件（受版权法保护）和自由软件（如 TCP/IP、Linux、Apache 服务器软件）三类。","4、==数据的整体结构化==：数据库系统实现整体数据的结构化，这是数据库的主要特征之一，也是数据库系统与文件系统的本质区别。 在文件系统中，文件中的记录内部具有结构，但记录的结构和记录之间的联系被固化在程序中，需要由程序员加以维护。这种工作模式既加重了程序员的负担，又不利于结构的变动。 所谓“整体”结构化，是指==数据库中的数据不再仅仅针对某一个应用==，而是面向整个组织或企业；不仅数据内部是结构化的，而且整体是结构化的，数据之间具有联系。也就是说，不仅要考虑某个应用的数据结构，还要考虑整个组织的数据结构。","5、==操作系统的其他配套软件==：^^其他配套软件^^：==图形用户界面（GUI）==；实用程序：任务管理器、磁盘碎片整理程序、防火墙、杀毒软件等；为其他应用程序开发与运行提供平台：应用框架、程序库、编译器等；常用的应用程序：日历、资源管理器等。","==三、操作系统的三大家族==","6、==丰富格式文本的兼容与 RTF 格式==：==一般来说==，不同软件制作的丰富格式文本相互不兼容；为了兼容，一些公司提出了中间格式，称为 RTF 格式。","7、==Photoshop 及其主要功能==：最著名的图像处理软件是美国 Adobe 公司的 PhotoShop，主要功能有滤镜操作、文字编辑、图层操作等。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-1-2-b6","imp":"core","kind":"tip","text":"软件分为两大类：==系统软件（负责管理、控制和维护计算机软硬件资源，为应用软件提供运行环境）==与==应用软件（为解决特定应用领域问题而专门开发的程序）==；系统软件主要包括：操作系统、语言处理程序（编译器/解释器/汇编器）、数据库管理系统（DBMS）、系统实用程序（驱动程序、磁盘工具等）。","title":"考向复习提示：系统软件 vs 应用软件标准划分"},{"t":"callout","id":"a2-2-1-2-b7","imp":"core","kind":"trap","text":"专转本高频陷阱题：==MySQL、Oracle 等数据库管理系统（DBMS）属于“系统软件”==，而不是应用软件！考生容易因为平时用 SQL 语句写业务，误将其归为应用软件；在专转本大纲标准答案中，DBMS 是支撑性系统软件！","title":"高频易错陷阱：数据库管理系统（DBMS）的归属"}]$kba212$::jsonb, $kba212se$A2-2.1.2 软件的分类。 1、计算机系统由硬件系统和软件系统两部分构成。 （1）硬件系统:运算器、控制器、存储器、输入设备、输出设备等五大部件 （2）软件系统：系统软件和应用软件。 ①、系统软件：操作系统、数据库管理系统、程序设计语言处理系统等 ②、应用软件：文字处理软件、通信软件、图像处理软件等2 软件： （1）软件=程序+数据+相关文档。 （2）程序就是要计算机做什么或完成什么功能的一组指令（语句），这些指令能够被计算机理解并执行的命令。 （3）数据：就是计算机执行程序过程中的输入数据和输出数据。 （4）相关文档就是程序开发、维护和操作有关的资料，不可缺少。 （5）程序的特性： ①、不可见性∶是无形的，不能被人们直接观察、欣赏和评价。 ②、适用性∶可以适应一类应用问题的需要。 ③、依附性∶依附于特定的硬件、网络和其他软件。 ④、复杂性∶规模越来越大，人力和物力消耗越来越高。 ⑤、无磨损性∶功能和性能一般不会发生变化。 ⑥、易复制性∶可以非常容易且无失真地进行复制。 ⑦、不断演化∶有生命周期。 ⑧、有限责任∶具有有限保证。 ⑨、脆弱性∶容易遭受黑客、病毒、信息盗用等损害。 （6）程序与数据的关系： ①、程序所处理的对象和处理后得到的结果统称为数据（分别称为输入数据和输出数据） ②、程序需要有合理输入数据，才会产生有意义的输出数据 ③、给同一个程序输入不同的数据，可以得到不同的输出数据 ④、给不同的程序输入相同的数据，可以得到不同的输出数据 （7）软件的特点 ①、软件是一种逻辑实体，具有抽象性； ②、软件的生产与硬件不同，它没有明显的制作过程； ③、软件在运行、使用期间不存在磨损、老化问题； ④、软件的开发、运行对计算机系统具有依赖性，受计算机系统的限制，这导致了软件移植的问题； ⑤、软件复杂性高（固有有），成本昂贵； ⑥、软件开发涉及诸多的社会因素。 3 软件分类： （1）按软件用途和功能作用分： ①、应用软件：专门用于帮助最终用户解决各种具体应用问题的软件。 可以分为定制应用软件和通用应用软件。 文字处理类 记事本Notepad（纯文本）、写字板Wordpad、微软Word、金山WPS 文字、 永中Office、Acrobat Reader 等 文字输入类 智能ABC、微软拼音、搜狗拼音、极品五笔、拼音加加、谷歌拼音 电子表格类 微软Excel、WPS 表格（金山公司，国产）等。 演示类 幻灯片 微软PowerPoint、 WPS 演示（金山公司，国产）等 网页制作类 FrontPage、Dreamweaver、Web Page Maker、ASP Maker 网页浏览类 微软IE、傲游Maxthon、腾讯TT、Mozilla Firefox 搜索引擎类 Baidu、Google、北大天网、搜狐Sogou、新浪爱问、网易有道、雅虎易搜 杀毒软件类 瑞星、诺顿、卡巴斯基、金山毒霸、江民KV、趋势科技 软件防火墙类 瑞星个人防火墙、江民防火墙、360 防火墙、天网防火墙、风云防火墙 图像处理类 Paint、Photo Editor、PhotoImpact、ACDSee32、Adobe Photoshop 矢量绘图软件 Corel Draw、Illustrator、Freehand、Microsoft Visio、Adobe Flash、3D Max 数字视频编辑软件 Adobe Premiere、Windows Movie Maker、Video Edit Magic、PowerDirector 数字声音编辑软件 CoolEdit、GoldWave、Adobe Audition、Nero wave Editor 媒体播放软件 暴风影音、Windows Media Player、RealPlayer、QuickTime、千千静听、 Winamp 网络聊天类 腾讯QQ、微软MSN、网易POPO、新浪UC、移动飞信、阿里旺旺 解/压缩类 WinRAR、WinZip、7-Zip、ChinaZip、Zipghost 下载工具类 迅雷Thunder、网际快车FlashGet、比特彗星BitComet、电驴emule、腾讯旋风 邮件收发类 Outlook Express、Foxmail、DreamMail、Koomail、U-Mail 网络电视类 PPlive、PPStream、QQLive、UUsee、TVKoo、CCTV Box、迅雷看看 FTP 工具类 Serv-U FTP、CuteFTP、TurboFTP、ChinaFTP、LeapFTP ②、系统软件：系统软件是给用户使用计算机提供方便、为应用软件的运行和开发提供服务与支持、使计算机安全可靠高效地运行的必不可少的软件 操作系统（OS） Windows、Unix、Linux、安卓、HarmonyOS（鸿蒙OS）等 基本输入/输出系统 BIOS 程序开发工具与环境 编译器、解释器、汇编程序（汇编器）、开发工具与平台 数据库管理系统(DBMS) MySQL 、Oracle 、Access 、DB2 、SQL Server 、Sybase 、VFP 、 PostgreSQL、NoSQL（大数据中常用：BigTable、Redis、MongoDB、 Neo4J、Hazelcast） 实用程序 磁盘清理程序、备份程序、杀毒软件、防火墙等 （2）按知识产权分： ①、商品软件：得先购买后使用，受到版权和许可证保护。 例如：Windows 操作系统等 ②、共享软件（试用软件）：具有版权，可免费试用一段时间，允许拷贝和散发（但不可修改），试用期满后需交费才能继续使用例如：微软Visio 等 ③、自由软件（开源软件）：用户可共享，并允许随意拷贝、修改其源代码，允许销售和自由传播。 例如：Linux(CentOS)、Linux(Ubuntu)等 ④、免费软件：无需付费即可获得的软件。例如 PDF 阅读器、Flash 播放器、QQ、微信等自由软件很多是免费软件；免费软件不全是自由软件4 软件版本 （1）版权授予软件作者(版权所有者)享有下列权利：拷贝、发布、修改、署名、出售、等 （2）软件许可证也称为“许可证协议”，它规定了计算机软件使用方式的法律合同，软件使用有哪些额外的限制，有哪些额外的权利等 （3）许可证的类型：单用户许可证、多用户许可证、并发用户许可证、定点许可证等。 （4）用户购买了一个软件后，仅仅得到了该软件的使用权，并没有它的版权。 （5）通过购买多用户许可证，允许将一个软件安装在若干台计算机上使用，或者允许所安装的一份软件同时被若干用户使用。 2、数据库管理系统（DBMS） 了解了数据和数据库的概念，下一个问题就是如何科学地组织和存储数据、如何高效地获取和维护数据，完成这个任务的是一个系统软件——数据库管理系统。 数据库管理系统是位于用户与操作系统之间的一层数据管理软件。 数据库管理系统和操作系统一样是计算机的基础软件，也是一个大型复杂的软件系统。 它的主要功能包括： （1）数据定义功能 （2）数据组织、存储和管理 （3）数据操纵功能 （4）数据库的事务管理和运行管理 （5）数据库的建立和维护功能等。 3、按软件权益分类：按软件权益分：软件分为商品软件（受所有法律保护）、共享软件（受版权法保护）和自由软件（如 TCP/IP、Linux、Apache 服务器软件）三类。 4、数据的整体结构化：数据库系统实现整体数据的结构化，这是数据库的主要特征之一，也是数据库系统与文件系统的本质区别。 在文件系统中，文件中的记录内部具有结构，但记录的结构和记录之间的联系被固化在程序中，需要由程序员加以维护。这种工作模式既加重了程序员的负担，又不利于结构的变动。 所谓“整体”结构化，是指数据库中的数据不再仅仅针对某一个应用，而是面向整个组织或企业；不仅数据内部是结构化的，而且整体是结构化的，数据之间具有联系。也就是说，不仅要考虑某个应用的数据结构，还要考虑整个组织的数据结构。 5、操作系统的其他配套软件：其他配套软件：图形用户界面（GUI）；实用程序：任务管理器、磁盘碎片整理程序、防火墙、杀毒软件等；为其他应用程序开发与运行提供平台：应用框架、程序库、编译器等；常用的应用程序：日历、资源管理器等。 三、操作系统的三大家族 6、丰富格式文本的兼容与 RTF 格式：一般来说，不同软件制作的丰富格式文本相互不兼容；为了兼容，一些公司提出了中间格式，称为 RTF 格式。 7、Photoshop 及其主要功能：最著名的图像处理软件是美国 Adobe 公司的 PhotoShop，主要功能有滤镜操作、文字编辑、图层操作等。 考向复习提示：系统软件 vs 应用软件标准划分 软件分为两大类：系统软件（负责管理、控制和维护计算机软硬件资源，为应用软件提供运行环境）与应用软件（为解决特定应用领域问题而专门开发的程序）；系统软件主要包括：操作系统、语言处理程序（编译器/解释器/汇编器）、数据库管理系统（DBMS）、系统实用程序（驱动程序、磁盘工具等）。 高频易错陷阱：数据库管理系统（DBMS）的归属 专转本高频陷阱题：MySQL、Oracle 等数据库管理系统（DBMS）属于“系统软件”，而不是应用软件！考生容易因为平时用 SQL 语句写业务，误将其归为应用软件；在专转本大纲标准答案中，DBMS 是支撑性系统软件！$kba212se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kba212 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
